prog='''from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = defaultdict(set)
    diag = defaultdict(set)
    horizontal = False
    for r, row in enumerate(grid):
        vals = set(row)
        if len(vals) == 1 and 0 not in vals:
            horizontal = True
            rows[r].add(row[0])
        for c, v in enumerate(row):
            if v:
                diag[c - r].add(v)
    if horizontal:
        n = len(rows)
        cm = {k % n: sorted(v)[0] for k, v in rows.items()}
        return [[cm[r % n] for c in range(w)] for r in range(h)]
    n = len(diag)
    if n == 0:
        return [row[:] for row in grid]
    cm = {k % n: sorted(v)[0] for k, v in diag.items()}
    return [[cm[(c - r) % n] for c in range(w)] for r in range(h)]
'''
